from pathlib import Path
import json,numpy as np,geopandas as g,shapely,pandas as pd
from shapely.strtree import STRtree
out=Path('data/user_shanghai');city=g.read_file('data/raw/shanghai_boundary.geojson').to_crs(32651).geometry.union_all();shapely.prepare(city);old=g.read_file('data/raw/osm/gis_osm_railways_free_1.shp').to_crs(32651);alltree=STRtree(old.geometry.to_numpy());ground=old[old.fclass.isin(['rail','light_rail','tram'])&(old.bridge!='T')&(old.tunnel!='T')&(old.layer.fillna(0)==0)];gtree=STRtree(ground.geometry.to_numpy());results=[];m=[]
for f,tag in [('national_rail.gpkg','national_2025'),('province_rail.gpkg','shanghai_province')]:
 x=g.read_file(out/f).to_crs(32651);x=x[x.fclass.isin(['rail','light_rail','tram'])&(x.bridge!='T')&(x.tunnel!='T')&(x.layer.fillna(0)==0)];x=x[shapely.intersects(city,x.geometry.array)].copy();clipped=shapely.intersection(x.geometry.array,city);length=shapely.length(clipped);keep=length>10;x=x.iloc[np.flatnonzero(keep)].copy();clipped=clipped[keep];length=length[keep];mid=shapely.line_interpolate_point(clipped,.5,normalized=True);_,dg=gtree.query_nearest(mid,return_distance=True,all_matches=False);_,da=alltree.query_nearest(mid,return_distance=True,all_matches=False);x.geometry=clipped;x['ground_dist_m']=dg;x['anyrail_dist_m']=da;x['source']=tag;x['review_reason']=np.where((dg>10)&(da<=10),'grade_or_type_difference','not_near_current_rail');c=x[dg>10].copy();cols=['name','fclass','ground_dist_m','anyrail_dist_m','source','review_reason','geometry'];results.append(c[cols]);m.append({'source':tag,'ground_records':len(x),'within_2m_length_share':float(length[dg<2].sum()/length.sum()),'within_10m_length_share':float(length[dg<10].sum()/length.sum()),'review_candidates':len(c),'grade_or_type_difference':int((c.review_reason=='grade_or_type_difference').sum())})
res=g.GeoDataFrame(pd.concat(results,ignore_index=True),crs=32651);res.to_file(out/'rail_review_candidates.gpkg',driver='GPKG');(out/'rail_audit.json').write_text(json.dumps(m,ensure_ascii=False,indent=2));print(json.dumps(m,ensure_ascii=False,indent=2))
